window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e18d9ae32a03baf7"]={"versions": [{"id": "FIG-e18d9ae32a03baf7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Prozessdiagramm (Software & Systems Process Engineering Metamodel) im Kontext der AUTOSAR-Classic-Methodik. Das Diagramm stellt den Ausschnitt des System- und ECU-Design-Prozesses dar und gliedert sich in vier Hauptbereiche (Packages/Swimlanes): „Software Component (SW-C)“, „Virtual Function Bus (VFB)“, „System“ sowie „ECU / Basic Software (BSW)“. Es visualisiert die Transformation von Systembeschreibungen über den ECU-Extrakt bis hin zur BSW- und ECU-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert Deliverables (Work Products, dargestellt als Paketumschläge), Dokumente/Modellelemente (Dokument-Icons mit Textzeilen) und Prozessaktivitäten (abgerundete Kacheln bzw. Prozessschritte):</p>\n<ul class=\"fig-list\">\n<li>Bereich „Software Component (SW-C)“: Dokument „Software Component Internal Behavior“.</li>\n<li>Bereich „Virtual Function Bus (VFB)“: Dokumente „VFB Atomic Software Component“ und „VFB Composition Component“, Deliverable „Delivered Atomic Software Components“ (aggregiert das interne Verhalten und die atomare Softwarekomponente).</li>\n<li>Bereich „System“: Deliverable „System Configuration Description“ (bestehend aus Aggregationen des Deliverables „Overall VFB System“, welches wiederum mit „VFB Composition Component“ verknüpft ist, sowie Erweiterung «extends» von „System Description“), Dokument „Communication Matrix“ (Teil der „System Description“), Aktivität „Generate ECU Extract“, Deliverable „ECU Extract“.</li>\n<li>Bereich „ECU / Basic Software (BSW)“: Deliverable „BSW Module Delivered Bundle“ (aggregiert „BSW Module“ mit Dokument „Basic Software Module Internal Behavior“), Dokument „Basic Software Module Description“, Aktivität „Configure ECUC“, Dokument „ECU Configuration Values“.</li>\n<li>Beziehungen/Stereotypen: «input» führt von „System Configuration Description“ zu „Generate ECU Extract“ und von „ECU Extract“ sowie „BSW Module Delivered Bundle“ zu „Configure ECUC“; «output» führt von „Generate ECU Extract“ zu „ECU Extract“; «inoutput» besteht bidirektional zwischen „Configure ECUC“ und „ECU Configuration Values“. Aggregationsrauten verbinden Deliverables mit ihren Teilkomponenten/Dokumenten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf vollzieht sich entlang der AUTOSAR-Entwurfskette:</p>\n<ol class=\"fig-list\">\n<li>Komponentenentwurf: Definition von SW-C Internal Behavior und VFB Atomic Software Components mündet in das Deliverable „Delivered Atomic Software Components“. Zusammen mit VFB Composition Components bildet dies das „Overall VFB System“.</li>\n<li>Systementwurf: Das „Overall VFB System“ wird in die „System Configuration Description“ integriert, welche die „System Description“ (inklusive Communication Matrix) erweitert.</li>\n<li>Extraktion: Die Aktivität „Generate ECU Extract“ nimmt die „System Configuration Description“ als «input» entgegen und erzeugt als «output» das Deliverable „ECU Extract“.</li>\n<li>Steuergeräte-Konfiguration: Der „ECU Extract“ wird zusammen mit dem „BSW Module Delivered Bundle“ als «input» an die Aktivität „Configure ECUC“ übergeben, die im Wechselspiel («inoutput») mit den „ECU Configuration Values“ die ECU- und BSW-Konfiguration vornimmt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert normative Schnittstellen und Artefakte des AUTOSAR-Methodenmodells (AUTOSAR Methodology). Entwickler und Toolhersteller von Timing- und Konfigurationswerkzeugen müssen sicherstellen, dass Systembeschreibungen die erforderlichen Kommunikations- und Verhaltensmodelle enthalten, um den normativen ECU-Extrakt für nachgelagerte BSW-Konfigurationswerkzeuge deterministisch generieren zu können. Timing-Constraints sind in den jeweiligen Beschreibungsdateien (SW-C Internal Behavior, System Description, BSW Module Description) konsistent zu führen.</p>"}, {"id": "FIG-55859d38d6895b24", "releases": ["R4.2.2", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Prozessdiagramm (Software & Systems Process Engineering Metamodel) im Kontext der AUTOSAR-Classic-Methodik. Das Diagramm stellt den Ausschnitt des System- und ECU-Design-Prozesses dar und gliedert sich in vier Hauptbereiche (Packages/Swimlanes): „Software Component (SW-C)“, „Virtual Function Bus (VFB)“, „System“ sowie „ECU / Basic Software (BSW)“. Es visualisiert die Transformation von Systembeschreibungen über den ECU-Extrakt bis hin zur BSW- und ECU-Konfiguration.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert Deliverables (Work Products, dargestellt als Paketumschläge), Dokumente/Modellelemente (Dokument-Icons mit Textzeilen) und Prozessaktivitäten (abgerundete Kacheln bzw. Prozessschritte):</p>\n<ul class=\"fig-list\">\n<li>Bereich „Software Component (SW-C)“: Dokument „Software Component Internal Behavior“.</li>\n<li>Bereich „Virtual Function Bus (VFB)“: Dokumente „VFB Atomic Software Component“ und „VFB Composition Component“, Deliverable „Delivered Atomic Software Components“ (aggregiert das interne Verhalten und die atomare Softwarekomponente).</li>\n<li>Bereich „System“: Deliverable „System Configuration Description“ (bestehend aus Aggregationen des Deliverables „Overall VFB System“, welches wiederum mit „VFB Composition Component“ verknüpft ist, sowie Erweiterung «extends» von „System Description“), Dokument „Communication Matrix“ (Teil der „System Description“), Aktivität „Generate ECU Extract“, Deliverable „ECU Extract“.</li>\n<li>Bereich „ECU / Basic Software (BSW)“: Deliverable „BSW Module Delivered Bundle“ (aggregiert „BSW Module“ mit Dokument „Basic Software Module Internal Behavior“), Dokument „Basic Software Module Description“, Aktivität „Configure ECUC“, Dokument „ECU Configuration Values“.</li>\n<li>Beziehungen/Stereotypen: «input» führt von „System Configuration Description“ zu „Generate ECU Extract“ und von „ECU Extract“ sowie „BSW Module Delivered Bundle“ zu „Configure ECUC“; «output» führt von „Generate ECU Extract“ zu „ECU Extract“; «inoutput» besteht bidirektional zwischen „Configure ECUC“ und „ECU Configuration Values“. Aggregationsrauten verbinden Deliverables mit ihren Teilkomponenten/Dokumenten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf vollzieht sich entlang der AUTOSAR-Entwurfskette:</p>\n<ol class=\"fig-list\">\n<li>Komponentenentwurf: Definition von SW-C Internal Behavior und VFB Atomic Software Components mündet in das Deliverable „Delivered Atomic Software Components“. Zusammen mit VFB Composition Components bildet dies das „Overall VFB System“.</li>\n<li>Systementwurf: Das „Overall VFB System“ wird in die „System Configuration Description“ integriert, welche die „System Description“ (inklusive Communication Matrix) erweitert.</li>\n<li>Extraktion: Die Aktivität „Generate ECU Extract“ nimmt die „System Configuration Description“ als «input» entgegen und erzeugt als «output» das Deliverable „ECU Extract“.</li>\n<li>Steuergeräte-Konfiguration: Der „ECU Extract“ wird zusammen mit dem „BSW Module Delivered Bundle“ als «input» an die Aktivität „Configure ECUC“ übergeben, die im Wechselspiel («inoutput») mit den „ECU Configuration Values“ die ECU- und BSW-Konfiguration vornimmt.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm illustriert normative Schnittstellen und Artefakte des AUTOSAR-Methodenmodells (AUTOSAR Methodology). Entwickler und Toolhersteller von Timing- und Konfigurationswerkzeugen müssen sicherstellen, dass Systembeschreibungen die erforderlichen Kommunikations- und Verhaltensmodelle enthalten, um den normativen ECU-Extrakt für nachgelagerte BSW-Konfigurationswerkzeuge deterministisch generieren zu können. Timing-Constraints sind in den jeweiligen Beschreibungsdateien (SW-C Internal Behavior, System Description, BSW Module Description) konsistent zu führen.</p>"}, {"id": "FIG-15347f539e8d8261", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Prozessdiagramm (Software & Systems Process Engineering Metamodel) der vollständigen AUTOSAR-Methodik für den Systementwurfsprozess („System design process“). Das Diagramm gliedert den Entwurfsworkflow über fünf funktionale Bereiche bzw. Swimlanes: „Basic Software“, „System“, „Virtual Functional Bus“, „Software Component“ und die abschließende Steuergeräteebene „ECU“. Es modelliert Aktivitäten, Deliverables (Work Products) sowie Kontroll- und Datenflüsse mit expliziten Multiplizitäten/Kardinalitäten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Aktivitäten (Prozessschritte) und Deliverables (Umschlag-Symbole) mit Ein-/Ausgangsbeziehungen («input», «output») und Kardinalitäten:</p>\n<ul class=\"fig-list\">\n<li>Bereich „Basic Software“: Deliverables „BSW Standard Package“ (Kardinalität 1) und „BSW Module Delivered Bundle“ (1..*); Aktivität „Develop Basic Software“.</li>\n<li>Bereich „System“: Aktivitäten „Develop an Abstract System Description“, „Develop System“ und „Develop Sub-System“; Deliverables „System Constraint Description“ (0..1), „Abstract System Description“ (0..<em> bzw. 1..</em>), „Transformer Design Bundle“ (0..<em>), „System Extract“ (0..</em> bzw. 1) und „ECU Extract“ (1..*).</li>\n<li>Bereich „Virtual Functional Bus“: Deliverable „VFB AUTOSAR Standard Package“ (1..*); Aktivität „Develop a VFB System Description“; Deliverable „Overall VFB System“ (0..1 bzw. 1).</li>\n<li>Bereich „Software Component“: Aktivität „Develop Application Software“; Deliverable „Delivered Atomic Software Components“ (1..*).</li>\n<li>Bereich „ECU“: Aktivität „Integrate Software for ECU“; Deliverable „ECU Software Delivered“ (Kardinalität 1).</li>\n<li>Schnittstellenflüsse:</li>\n<li>„Develop an Abstract System Description“: Input aus „System Constraint Description“ (0..1) und „VFB AUTOSAR Standard Package“ (1..<em>); Output ist „Abstract System Description“ (1..</em>).</li>\n<li>„Develop a VFB System Description“: Input aus „VFB AUTOSAR Standard Package“ (1..<em>) und „Abstract System Description“ (0..</em>); Output ist „Overall VFB System“ (1).</li>\n<li>„Develop System“: Input aus „System Constraint Description“ (0..1), „Abstract System Description“ (0..<em>) und „Overall VFB System“ (0..1); Output sind „Transformer Design Bundle“ (0..</em>), „System Extract“ (0..<em>) und „ECU Extract“ (1..</em>).</li>\n<li>„Develop Sub-System“: Input aus „System Extract“ (1); Output ist „ECU Extract“ (1..*).</li>\n<li>„Develop Basic Software“: Input aus „BSW Standard Package“ (1) und „Transformer Design Bundle“ (0..<em>); Output ist „BSW Module Delivered Bundle“ (1..</em>).</li>\n<li>„Develop Application Software“: Input aus „Overall VFB System“ (1); Output ist „Delivered Atomic Software Components“ (1..*).</li>\n<li>„Integrate Software for ECU“: Input aus „BSW Module Delivered Bundle“ (1..<em>), „ECU Extract“ (1) und „Delivered Atomic Software Components“ (1..</em>); Output ist „ECU Software Delivered“ (1).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der dynamische Ablauf folgt der hierarchischen Top-down- und Integrationsmethodik:</p>\n<ol class=\"fig-list\">\n<li>Abstrakte Systemdefinition: Ausgehend von „System Constraint Description“ und „VFB AUTOSAR Standard Package“ wird mittels „Develop an Abstract System Description“ eine „Abstract System Description“ erstellt.</li>\n<li>VFB-Entwurf: Aus dem Standard-Package und der abstrakten Systembeschreibung leitet „Develop a VFB System Description“ das „Overall VFB System“ ab.</li>\n<li>System- und Subsystementwicklung: „Develop System“ verarbeitet Randbedingungen, die abstrakte Beschreibung sowie das VFB-System. Daraus resultieren das „Transformer Design Bundle“, „System Extract“ für Subsysteme sowie der „ECU Extract“. Subsysteme werden über „Develop Sub-System“ iterativ verfeinert und speisen wiederum in den „ECU Extract“ ein.</li>\n<li>Parallele Komponenten- und BSW-Entwicklung: „Develop Basic Software“ nutzt das Standard-Paket und Transformer-Bundles zur Erzeugung der BSW-Module. Parallel entwickelt „Develop Application Software“ auf Basis des Overall VFB Systems die atomaren Softwarekomponenten.</li>\n<li>Steuergeräte-Integration: Die Aktivität „Integrate Software for ECU“ fusioniert BSW-Modulbündel, ECU-Extrakte und atomare Softwarekomponenten zur finalen „ECU Software Delivered“.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Prozess definiert den normativen methodischen Rahmen für AUTOSAR-Systementwürfe gemäß AUTOSAR Methodology. Für Timing-Analysen ist die Einhaltung der Kardinalitäten und Abhängigkeiten maßgeblich: Timing-Anforderungen aus der „System Constraint Description“ propagieren über System- und ECU-Extrakte in die BSW- und Komponentenentwicklung und müssen bei der finalen Steuergeräteintegration („Integrate Software for ECU“) gegen die synthetisierte Gesamtsoftware validiert werden. Die Unterstützung von Transformer-Bundles und Subsystem-Extrakten bedingt entsprechende Import-/Export-Fähigkeiten in den beteiligten Engineering-Werkzeugen.</p>"}], "trans": [{"from": "FIG-e18d9ae32a03baf7", "to": "FIG-55859d38d6895b24", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-55859d38d6895b24", "to": "FIG-15347f539e8d8261", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Das Prozessmodell wurde vollständig von einer vereinfachten Teilansicht (Generate ECU Extract, Configure ECUC) auf das umfassende SPEM-System-Design-Prozessmodell der AUTOSAR-Methodik umgestellt.</li>\n<li>Neue Aktivitäten hinzugefügt: „Develop an Abstract System Description“, „Develop a VFB System Description“, „Develop System“, „Develop Sub-System“, „Develop Basic Software“, „Develop Application Software“ und „Integrate Software for ECU“.</li>\n<li>Entfallene Aktivitäten: „Generate ECU Extract“ und „Configure ECUC“.</li>\n<li>Neue Work Products (Deliverables) mit formalen Kardinalitäten eingeführt: „BSW Standard Package“, „VFB AUTOSAR Standard Package“, „System Constraint Description“, „Abstract System Description“, „Transformer Design Bundle“, „System Extract“ und „ECU Software Delivered“.</li>\n<li>Geänderte Artefaktbeziehungen und Kardinalitäten: „System Configuration Description“, „System Description“, „Communication Matrix“, „VFB Atomic Software Component“, „VFB Composition Component“, „Software Component Internal Behavior“, „BSW Module Description“ und „ECU Configuration Values“ sind nicht mehr als separate Dokument-Icons modelliert.</li>\n<li>Neue Swimlanes/Bereiche: „Basic Software“, „System“, „Virtual Functional Bus“, „Software Component“ und „ECU“.</li>\n</ul>"}]};
